import {escapeHTML as h,formatARS as money,duration,dateLabel,dateInput,preview,statusLabel,normal} from './format.js';
import {icon,categoryIcon} from './icons.js';
export const button=(label,action,id='',cls='secondary',extra='')=>`<button class="btn ${cls}" data-action="${action}" data-id="${h(id)}" ${extra}>${label}</button>`;
export const link=(label,route,cls='secondary')=>`<a class="btn ${cls}" href="#${route}">${label}</a>`;
export function avatar(p,size=''){const slug=p?.is_demo&&['demo_ana','demo_mateo','demo_lucia','demo_carla','demo_santi'].includes(p.id)?p.id.slice(5):null;return `<span class="avatar ${size}">${slug?`<img src="/assets/photos/portrait-${slug}.webp" alt="" loading="lazy">`:h((p?.name||'INTERA').split(' ').slice(0,2).map(w=>w[0]).join(''))}</span>`;}
export const person=(ctx,id)=>ctx.data.people.find(p=>p.id===id)||{id,name:'Persona'};
export const photoFor=o=>o.is_demo?`/assets/photos/${o.category==='Tecnología'||o.category==='Programación'?'scene-tech':o.category==='Diseño'||o.category==='Fotografía'||o.category==='Redacción'?'scene-design':o.provider_id==='demo_carla'?'portrait-carla':'portrait-ana'}.webp`:null;
export const badge=(status,kind='')=>`<span class="badge ${kind||(['APPROVED','COMPLETED','CONNECTED'].includes(status)?'good':['CANCELLED','REJECTED','CHARGED_BACK'].includes(status)?'bad':['PENDING','REFUND_PENDING','DISPUTED','UNPAID','UNKNOWN'].includes(status)?'warning':'')}">${h(statusLabel(status))}</span>`;
export const empty=(title,description,cta='',type='search')=>`<section class="empty">${icon(type)}<h3>${h(title)}</h3><p>${h(description)}</p>${cta}</section>`;
export const head=(title,subtitle='',actions='',eyebrow='INTERA · SERVICIOS')=>`<header class="page-head" data-enter><div><div class="eyebrow">${h(eyebrow)}</div><h1>${h(title)}</h1>${subtitle?`<p>${h(subtitle)}</p>`:''}</div>${actions?`<div class="actions">${actions}</div>`:''}</header>`;
export function notice(content,type=''){return `<div class="notice ${type}">${icon(type==='success'?'check':'info')}<div>${content}</div></div>`;}
export function quoteBox(price,blocks,{seller=false,totalLabel='Total del servicio'}={}){let q;try{q=preview(Number(price),Number(blocks));}catch{return notice('Elegí una tarifa y cantidad de bloques válidas.');}return `<div class="breakdown"><div class="line"><span>${blocks} bloque${blocks===1?'':'s'} × ${money(price*100)}</span><strong>${duration(blocks)}</strong></div><div class="line total"><span>${h(totalLabel)}</span><strong>${money(q.grossCents)}</strong></div><div class="line"><span>Comisión INTERA · 5% del bruto</span><strong>${money(q.commissionCents)}</strong></div><div class="line"><span>Prestador, antes de cargos externos</span><strong>${money(q.sellerBeforeProcessorCents)}</strong></div><p>${seller?'La comisión se descuenta del cobro; no se agrega al total del cliente.':'El 5% está incluido: no se agrega como un recargo al total del servicio.'} Los cargos de Mercado Pago y las retenciones aplicables se descuentan por separado. El neto y la fecha de disponibilidad los informa Mercado Pago.</p></div>`;}
export function consentBanner(ctx){if(!ctx.user)return '';if(ctx.user.suspended)return notice('Tu cuenta tiene operaciones restringidas. Conservás acceso al historial, exportación y <a class="text-link" href="#/ayuda">reclamos</a>.','warning');if(!ctx.user.emailVerified)return `<div class="notice warning consent-banner"><div><strong>Verificá tu correo para operar.</strong><br>Te enviamos un enlace. En simulación, se muestra dentro de la aplicación.</div>${button('Reenviar verificación','resend','','secondary small')}</div>`;if(!ctx.session.conditionsAccepted)return `<div class="notice warning consent-banner"><div><strong>Tenemos un nuevo modelo de servicios pagos.</strong><br>Leé y aceptá las condiciones antes de publicar, contratar o cobrar.</div>${button('Leer y aceptar','terms','','secondary small')}</div>`;return '';}
export function shell(ctx,content){const route=ctx.route;const navigation=[['/','home','Inicio'],['/explorar','search','Explorar'],['/necesidades','list','Necesidades'],['/ordenes','swap','Mis servicios'],['/agenda','calendar','Agenda'],['/movimientos','wallet','Pagos y cobros']];const pending=ctx.data.bookings.filter(b=>b.status==='REQUESTED'&&b.seller_id===ctx.user?.id||b.status==='COMPLETED_BY_PROVIDER'&&b.buyer_id===ctx.user?.id).length;
 const nav=(p,i,title)=>`<a class="nav-item ${route===p?'active':''}" href="#${p}">${icon(i)}${title}${p==='/ordenes'&&pending?`<span class="count">${pending}</span>`:''}</a>`;
 return `<div class="shell"><aside class="sidebar"><a class="brand" href="#/"><img src="/assets/intera-mark.svg" alt="">intera</a><div class="nav-group-label">TU COMUNIDAD</div><nav aria-label="Principal">${navigation.map(n=>nav(...n)).join('')}</nav><div class="nav-group-label">TU ESPACIO</div>${nav('/prestador','briefcase','Soy prestador')}${nav('/perfil','user','Mi perfil')}${nav('/ayuda','help','Ayuda y reclamos')}<div class="sidebar-bottom"><div class="sidebar-note">${icon('clock')}<strong>15 minutos. Algo resuelto.</strong>Tarifas claras, elegidas por quien ofrece. Vos elegís con quién conectar.</div><a class="nav-item" href="#/condiciones">${icon('shield')}Condiciones del servicio</a></div></aside><div class="workspace"><header class="topbar"><a class="brand mobile-brand" href="#/"><img src="/assets/intera-mark.svg" alt="">intera</a><button class="global-search" data-action="search" aria-label="Buscar en INTERA">${icon('search')}<span>¿Qué necesitás resolver?</span><kbd>⌘ K</kbd></button><div class="topbar-right"><span class="topbar-location">${icon('pin','tiny-icon')} ${h(ctx.user?.neighborhood||'Comunidad CABA')}</span><button class="icon-btn theme-btn" data-action="theme" aria-label="Cambiar tema">${icon(ctx.theme==='dark'?'sun':'moon')}</button><button class="icon-btn" data-action="activity" aria-label="Ver actividad pendiente">${icon('bell')}${pending?`<span class="small">${pending}</span>`:''}</button>${ctx.user?`<button class="account-btn" data-action="account" aria-label="Abrir mi cuenta">${avatar(ctx.user)}<strong>${h(ctx.user.name.split(' ')[0])}</strong></button>`:link('Ingresar','/acceso','small')}</div></header><div class="mode-strip ${ctx.config.mode==='live'?'live':''}"><span class="mode-dot"></span><strong>${ctx.config.mode==='mock'?'SIMULADOR LOCAL · SIN DINERO REAL':ctx.config.mode==='sandbox'?'PRUEBAS MERCADO PAGO · SIN COBROS REALES':'PAGOS CON MERCADO PAGO'}</strong><span class="mode-extra">${ctx.config.mode==='mock'?'Perfiles y fotos de ejemplo':'Cuenta y disponibilidad según el proveedor de pagos'}</span>${ctx.config.mode==='mock'?'<button data-action="demo">Cambiar perfil de prueba</button>':''}</div><main id="main" class="content" tabindex="-1">${consentBanner(ctx)}${content}<footer class="footer"><span>INTERA 5.0 · Bloques de 15 minutos · ARS</span><div class="links"><a href="#/condiciones">Condiciones y privacidad</a><a href="#/ayuda">Reclamos</a><button class="compare-button" data-action="settings">Experiencia visual</button></div></footer></main></div><nav class="bottom-nav" aria-label="Navegación móvil">${[['/','home','Inicio'],['/explorar','search','Explorar'],['/publicar','plus','Ofrecer'],['/ordenes','swap','Servicios'],['/perfil','user','Mi espacio']].map(([p,i,t])=>`<a href="#${p}" class="${route===p?'active':''} ${p==='/publicar'?'central':''}">${icon(i)}${t}</a>`).join('')}</nav>${compareTray(ctx)}</div>`;
}
export function offerCard(ctx,o){const saved=ctx.data.favorites.includes(o.id),selected=ctx.compare.includes(o.id),src=photoFor(o);return `<article class="offer-card" data-enter><div class="offer-photo">${src?`<img src="${src}" alt="Imagen ilustrativa de demostración" loading="lazy"><div class="photo-tint"></div>`:icon(categoryIcon(o.category))}<span class="photo-label">${icon('tech')}Remoto · 18+</span><button class="offer-save" data-action="favorite" data-id="${h(o.id)}" aria-label="${saved?'Quitar de':'Agregar a'} guardados: ${h(o.title)}" aria-pressed="${saved}">${icon('heart')}</button></div><div class="offer-content"><a href="#/perfil/${h(o.provider_id)}" class="provider-line">${avatar(person(ctx,o.provider_id))}<span>${h(o.provider_name)}</span></a><h3><a href="#/oferta/${h(o.id)}">${h(o.title)}</a></h3><p class="description">${h(o.description)}</p><div class="card-price">${money(o.price_ars*100)} <small>/ bloque de 15 min</small></div><div class="row spread"><span class="availability ${o.ready?'':'waiting'}">${o.ready?'● Cuenta vinculada':'○ Activación pendiente'}</span><button class="compare-button" data-action="compare" data-id="${h(o.id)}" aria-pressed="${selected}">${icon(selected?'check':'compare')}${selected?'Agregada':'Comparar'}</button></div><div class="card-bottom"><span class="small muted">${duration(o.blocks)} habitual</span>${button('Ver servicio '+icon('arrow'),'quick',o.id,'secondary small')}</div></div></article>`;}
export function categories(ctx,active='',onExplore=false){return `<div class="category-strip" aria-label="Categorías">${['Todas',...ctx.data.categories].map(c=>`<button class="category-pill ${(c==='Todas'&&!active)||c===active?'active':''}" data-action="category" data-id="${h(c==='Todas'?'':c)}" ${onExplore?'data-local="1"':''}>${icon(c==='Todas'?'spark':categoryIcon(c))}${h(c)}</button>`).join('')}</div>`;}
export function home(ctx){const offers=ctx.data.offers.filter(o=>o.active&&o.provider_id!==ctx.user?.id);const first=ctx.user?.name.split(' ')[0]||'tu próxima conexión';const completed=ctx.data.bookings.filter(b=>b.status==='COMPLETED').length,active=ctx.data.bookings.filter(b=>!['COMPLETED','CANCELLED'].includes(b.status));return `${head(ctx.user?'Hola, '+first+'.':'Conectá con lo que necesitás.','Tu tiempo tiene valor. Encontrá a alguien que te ayude a avanzar.',link(icon('plus')+' Ofrecer un servicio','/publicar',''),ctx.user?'BUENO VERTE POR ACÁ':'HECHO DE PERSONAS')}<section class="hero" data-enter><div class="hero-copy"><div class="eyebrow">${icon('spark')}TU PRÓXIMA BUENA CONEXIÓN</div><h2>Pequeños bloques.<br>Grandes soluciones.</h2><p>Contratá ayuda en bloques de 15 minutos. Tres tarifas claras. Personas con algo valioso para ofrecer.</p><div class="actions">${link('Encontrá tu servicio '+icon('arrow'),'/explorar','white')}${button('Cómo funciona','how','','soft-white')}</div></div><div class="hero-art" aria-hidden="true"><div class="orb"></div><div class="orb two"></div><img class="hero-person" src="/assets/photos/portrait-ana.webp" alt=""><img class="hero-person second" src="/assets/photos/portrait-mateo.webp" alt=""><span class="floating-tag top">${icon('clock')}15 min para avanzar</span><span class="floating-tag bottom">${icon('shield')}Precios claros, sin sorpresas</span>${icon('spark','soft-spark')}</div></section><div class="balance-row"><div class="mini-stat"><span class="stat-icon">${icon('clock')}</span><div><strong>15 min</strong><small>Cada bloque de servicio</small></div></div><div class="mini-stat"><span class="stat-icon">${icon('wallet')}</span><div><strong>3 tarifas</strong><small>$1.000 · $2.500 · $5.000</small></div></div><div class="mini-stat"><span class="stat-icon">${icon('check')}</span><div><strong>${ctx.user?completed:'5%'}</strong><small>${ctx.user?'Servicios completados':'Comisión de INTERA sobre el bruto'}</small></div></div></div>${ctx.config.mode==='mock'?`<div class="demo-guide"><div><strong>Probá ambos lados del nuevo modelo.</strong><p>Primero activá a Mateo como prestador. Después entrá como Ana para solicitar y pagar en el simulador.</p></div><div class="actions">${button('1 · Activar a Mateo','demo-user','demo_mateo','secondary small')}${button('2 · Contratar como Ana','demo-user','demo_ana','ghost small')}</div></div>`:''}<section class="section"><div class="section-head"><h2>¿Qué te gustaría resolver?</h2><a href="#/explorar">Ver todas ${icon('arrow','tiny-icon')}</a></div>${categories(ctx)}</section><section class="section"><div class="section-head"><h2>Habilidades que conectan</h2><span class="small muted">${offers.length} servicios publicados</span></div>${offers.length?`<div class="offer-grid">${offers.slice(0,6).map(o=>offerCard(ctx,o)).join('')}</div>`:empty('La comunidad empieza con vos','Publicá tu primera habilidad o dejá una necesidad para encontrar una buena conexión.',link('Ofrecer un servicio','/publicar',''))}</section><section class="section split"><div class="panel"><div class="section-head"><h2>Tu próxima acción</h2><a href="#/ordenes">Ver servicios ${icon('arrow','tiny-icon')}</a></div>${active.length?active.slice(0,3).map(b=>`<a class="list-row" href="#/orden/${h(b.id)}">${avatar(person(ctx,b.buyer_id===ctx.user.id?b.seller_id:b.buyer_id))}<div class="grow"><strong>${h(b.title)}</strong><small>${h(statusLabel(b.status))}</small></div>${icon('chevron')}</a>`):`<p class="muted small">${ctx.user?'No tenés acciones pendientes. Explorá una habilidad o compartí la tuya.':'Ingresá para organizar tus solicitudes y próximos servicios.'}</p>${link('Explorar servicios','/explorar','ghost small')}`}</div><div class="panel accent"><h2>Así de simple.</h2>${[['Elegí una habilidad','Cada prestador elige una de las tres tarifas por bloque.'],['Acordá y pagá','El prestador acepta. Luego pagás mediante Mercado Pago.'],['Recibí ayuda y valorá','Al terminar, confirmás el servicio y compartís tu experiencia.']].map(([t,d],i)=>`<div class="step-tile"><span class="step-num">${i+1}</span><div><strong class="small">${t}</strong><p>${d}</p></div></div>`).join('')}</div></section>`;}
export function filteredOffers(ctx){const f=ctx.filters;let offers=ctx.data.offers.filter(o=>o.active&&(!f.category||o.category===f.category)&&(!f.price||o.price_ars===Number(f.price))&&(!f.neighborhood||o.neighborhood===f.neighborhood)&&(!f.saved||ctx.data.favorites.includes(o.id))&&(!f.q||normal(o.title+' '+o.description+' '+o.provider_name+' '+o.category).includes(normal(f.q))));if(f.sort==='price')offers.sort((a,b)=>a.price_ars-b.price_ars);if(f.sort==='duration')offers.sort((a,b)=>a.blocks-b.blocks);return offers;}
export function explore(ctx){const f=ctx.filters,offers=filteredOffers(ctx);return `${head('Encontrá tu próxima conexión.','Ayuda concreta, en el tiempo que necesitás. Siempre sabés cuánto vas a pagar.',button(icon('heart')+' Guardados','show-saved','','secondary',`aria-pressed="${!!f.saved}"`),'EXPLORAR')} ${categories(ctx,f.category,true)}<form class="top-filters" data-form="filters"><label class="search-input"><span class="sr-only" hidden>Buscar servicios</span>${icon('search')}<input name="q" aria-label="Buscar servicios" placeholder="Una habilidad, una idea, algo por resolver…" value="${h(f.q||'')}"></label><select name="price" aria-label="Precio por bloque"><option value="">Todas las tarifas</option>${[1000,2500,5000].map(p=>`<option value="${p}" ${Number(f.price)===p?'selected':''}>${money(p*100)} / bloque</option>`).join('')}</select><select name="neighborhood" aria-label="Barrio"><option value="">Todos los barrios</option>${ctx.data.neighborhoods.map(n=>`<option ${f.neighborhood===n?'selected':''}>${h(n)}</option>`).join('')}</select><select name="sort" aria-label="Ordenar"><option value="">Más recientes</option><option value="price" ${f.sort==='price'?'selected':''}>Menor precio</option><option value="duration" ${f.sort==='duration'?'selected':''}>Menor duración</option></select><button class="btn" type="submit">${icon('filter')}Filtrar</button></form><div class="section-head"><span class="small muted">${offers.length} resultado${offers.length===1?'':'s'}${f.saved?' guardado'+(offers.length===1?'':'s'):''} · solo servicios remotos para adultos</span>${button('Limpiar filtros','clear-filters','','ghost small')}</div>${offers.length?`<div class="offer-grid">${offers.map(o=>offerCard(ctx,o)).join('')}</div>`:empty('Todavía no hay una coincidencia','Probá otra búsqueda o publicá qué necesitás.',button('Limpiar filtros','clear-filters','','')+' '+link('Publicar necesidad','/necesidades','secondary'))}`;}
export function offerDetail(ctx,o){if(!o)return empty('Publicación no disponible','Puede estar pausada o no ser visible para tu cuenta.',link('Volver a explorar','/explorar',''));const own=o.provider_id===ctx.user?.id,p=person(ctx,o.provider_id),src=photoFor(o);return `${head('Un poco de ayuda. Mucho por avanzar.','Conocé la propuesta antes de acordar el servicio.',link(icon('arrow')+' Explorar','/explorar','secondary small'),'DETALLE DEL SERVICIO')}<div class="split"><section><div class="panel"><div class="detail-heading">${src?`<img class="thumb" src="${src}" alt="Imagen ilustrativa de demostración">`:icon(categoryIcon(o.category))}<div><div class="eyebrow">${h(o.category)}</div><h1>${h(o.title)}</h1><p>${icon('tech','tiny-icon')} Remoto · ${h(o.neighborhood)} · 18+</p></div></div><h3>Qué podemos resolver</h3><p style="white-space:pre-wrap">${h(o.description)}</p><div class="row"><span class="badge neutral">${icon('clock','tiny-icon')}${duration(o.blocks)} habitual</span><span class="badge neutral">${h(o.availability)}</span></div></div><div class="panel section"><div class="party">${avatar(p,'lg')}<div><h3>${h(p.name)}</h3><p class="small muted">${h(p.neighborhood)}${p.is_demo?' · Perfil de ejemplo':''}</p></div></div><p class="muted small" style="margin-top:17px">${h(p.bio)}</p><div class="row">${link('Ver perfil','/perfil/'+p.id,'secondary small')}${!own?button('Reportar','report-profile',p.id,'ghost small'):''}</div></div></section><aside class="panel sticky-panel"><div class="eyebrow">TU SERVICIO, A TU RITMO</div><div class="card-price" style="font-size:37px">${money(o.price_ars*100)} <small>/ bloque de 15 minutos</small></div>${quoteBox(o.price_ars,o.blocks)}${own?link('Editar mi publicación','/publicar?edit='+o.id,'full'):o.ready?button('Acordar este servicio '+icon('arrow'),'book',o.id,'full'):notice('El prestador todavía debe aceptar las condiciones y vincular su cuenta antes de recibir contrataciones.','warning')}<div class="row" style="margin-top:12px">${button(icon('heart')+' Guardar','favorite',o.id,'secondary small')}${button(icon('compare')+' Comparar','compare',o.id,'ghost small')}</div><p class="small muted" style="margin-top:16px">Primero enviás una solicitud. El pago se habilita cuando el prestador acepta. No compartas contraseñas ni datos de tarjetas por chat.</p></aside></div>`;}
export function publish(ctx,o=null){if(!ctx.user)return accessRequired('Compartí lo que sabés hacer.');const p=o?.price_ars||2500,b=o?.blocks||2;return `${head(o?'Editá tu propuesta.':'Algo que sabés hacer. Alguien que lo necesita.','Elegí una de las tres tarifas. Las órdenes ya pactadas conservarán su precio.',link('Mi espacio de prestador','/prestador','secondary small'),'OFRECER UN SERVICIO')}<div class="split"><section class="panel"><form data-form="publish" data-id="${h(o?.id||'')}"><label class="field">Título del servicio<input name="title" required minlength="6" maxlength="100" value="${h(o?.title||'')}" placeholder="Por ejemplo: te ayudo a ordenar tu Excel"></label><div class="form-grid"><label class="field">Categoría<select name="category">${ctx.data.categories.map(c=>`<option ${o?.category===c?'selected':''}>${h(c)}</option>`).join('')}</select></label><label class="field">Barrio de tu perfil<select name="neighborhood">${ctx.data.neighborhoods.map(n=>`<option ${(o?.neighborhood||ctx.user.neighborhood)===n?'selected':''}>${h(n)}</option>`).join('')}</select></label></div><label class="field">Qué incluye y qué no incluye<textarea name="description" required minlength="20" maxlength="2000" rows="5" placeholder="Contá qué van a trabajar, qué necesitás y qué se lleva la otra persona.">${h(o?.description||'')}</textarea></label><label class="field">Disponibilidad orientativa<input name="availability" maxlength="200" required value="${h(o?.availability||'Días hábiles · horario a coordinar')}"></label><div class="eyebrow">TU TARIFA POR CADA BLOQUE DE 15 MINUTOS</div><div class="price-options">${[1000,2500,5000].map(v=>`<label class="price-option"><input type="radio" name="priceArs" value="${v}" ${v===p?'checked':''}><span>${money(v*100)}<small>ARS / 15 minutos</small></span></label>`).join('')}</div><label class="field">Duración habitual, en bloques<input name="blocks" type="number" min="1" max="32" step="1" value="${b}" required><small>1 bloque = 15 minutos. De 1 a 32 bloques. La duración se confirma en cada orden.</small></label>${notice('Esta entrega habilita servicios remotos para personas adultas. No se ofrecen atención de salud, cuidados, tareas con menores ni profesiones reguladas.')}<label class="check-label"><input type="checkbox" name="sellerFeeAccepted" required><span>Acepto que INTERA descuente el <strong>5% del bruto</strong> por intermediación. Los cargos de Mercado Pago y las retenciones aplicables se descuentan por separado. Me corresponde informar y emitir los comprobantes de mi servicio.</span></label><div class="form-error" role="alert"></div><button type="submit" class="btn full">${icon('plus')}${o?'Guardar cambios':'Publicar mi servicio'}</button></form></section><aside class="panel sticky-panel"><div class="eyebrow">VISTA PREVIA · CÁLCULO ORIENTATIVO</div><h2 id="preview-title">${h(o?.title||'Tu próxima propuesta')}</h2><p class="muted small">El servidor valida el importe y guarda una cotización inmutable al contratar.</p><div id="price-preview">${quoteBox(p,b,{seller:true})}</div>${notice('No se guarda un saldo en INTERA. El cobro se procesa en la cuenta del prestador, con Split 1:1 de Mercado Pago.')}<div class="small muted">${ctx.data.seller?.status==='CONNECTED'?'Tu cuenta de cobro está vinculada.':'Podés publicar ahora y vincular tu cuenta desde «Soy prestador» para recibir contrataciones.'}</div></aside></div>`;}
export const accessRequired=(title='Tu próximo paso empieza acá.')=>head(title,'Ingresá para acceder a tus servicios, pagos y conversaciones.')+empty('Tu espacio es personal','Cada cuenta ve únicamente sus propias operaciones.',link('Ingresar','/acceso','')+' '+link('Crear cuenta','/registro','secondary'),'user');
export function orders(ctx){if(!ctx.user)return accessRequired();const filtered=ctx.data.bookings.filter(b=>ctx.orderFilter==='all'||ctx.orderFilter==='buyer'&&b.buyer_id===ctx.user.id||ctx.orderFilter==='seller'&&b.seller_id===ctx.user.id||ctx.orderFilter==='active'&&!['COMPLETED','CANCELLED'].includes(b.status));return `${head('Mis servicios','Un lugar para acordar, conversar y seguir cada contratación.',button(icon('refresh')+' Actualizar','refresh','','secondary small'),'TU ACTIVIDAD')}<div class="category-strip">${[['all','Todos'],['buyer','Solicitados'],['seller','Como prestador'],['active','En curso o pendientes']].map(([v,t])=>button(t,'order-filter',v,ctx.orderFilter===v?'':'secondary',`aria-pressed="${ctx.orderFilter===v}"`)).join('')}</div><section class="section">${filtered.length?filtered.map(b=>orderCard(ctx,b)).join(''):empty('Todavía no hay servicios acá','Encontrá una habilidad y enviá tu primera solicitud.',link('Explorar servicios','/explorar',''),'swap')}</section>`;}
export function orderCard(ctx,b){return `<article class="order-card" data-enter><div class="row spread"><div><div class="row">${badge(b.status)}${badge(b.payment_status)}</div><h3><a href="#/orden/${h(b.id)}">${h(b.title)}</a></h3><div class="order-meta"><span>${icon('clock','tiny-icon')}${duration(b.blocks)}</span><span>${icon('calendar','tiny-icon')}${dateLabel(b.scheduled_at)}</span><span>${b.buyer_id===ctx.user.id?'Con '+h(b.seller_name):'Para '+h(b.buyer_name)}</span></div></div><div class="order-price"><strong>${money(b.gross_cents)}</strong><small class="muted">${b.blocks} × ${money(b.price_ars*100)}</small></div></div><div class="actions">${link('Ver orden '+icon('arrow'),'/orden/'+b.id,'secondary small')}${b.status==='REQUESTED'&&b.seller_id===ctx.user.id?button('Aceptar solicitud','accept',b.id,'small'):''}${b.status==='ACCEPTED'&&b.buyer_id===ctx.user.id&&['UNPAID','CHECKOUT_CREATED','PENDING','REJECTED'].includes(b.payment_status)?button('Ver pago','checkout',b.id,'small'):''}</div></article>`;}
export function orderDetail(ctx,d){const b=d.booking,seller=b.seller_id===ctx.user.id,other=seller?b.buyer_id:b.seller_id;const idx={REQUESTED:0,ACCEPTED:1,IN_PROGRESS:2,COMPLETED_BY_PROVIDER:3,COMPLETED:4}[b.status]??-1;let actionText='',actionButtons='';
 if(b.status==='REQUESTED'){actionText=seller?'Revisá duración, horario y alcance. Si aceptás, se habilitará el pago al solicitante.':'Tu solicitud está enviada. El prestador debe aceptarla antes de que puedas pagar.';if(seller)actionButtons=button('Aceptar servicio '+icon('check'),'accept',b.id,'');}
 else if(b.status==='ACCEPTED'&&b.payment_status==='APPROVED'){actionText=seller?'El pago está aprobado. Iniciá cuando comience el servicio. La disponibilidad del dinero se consulta en Mercado Pago.':'El pago está aprobado. Coordiná los últimos detalles con el prestador por chat.';if(seller)actionButtons=button('Iniciar servicio','start',b.id,'');}
 else if(b.status==='ACCEPTED'&&['UNPAID','CHECKOUT_CREATED','PENDING','REJECTED'].includes(b.payment_status)){actionText=seller?'Aceptaste la solicitud. Esperá un pago aprobado antes de prestar el servicio.':'El prestador aceptó. Revisá el total y continuá al checkout. Un pago pendiente no confirma la contratación.';if(!seller)actionButtons=button('Revisar y pagar '+icon('arrow'),'checkout',b.id,'');}
 else if(b.status==='IN_PROGRESS'){actionText=seller?'El servicio está en curso. Al finalizar, marcá tu parte completada.':'El servicio está en curso. Si necesitás más tiempo, pedile al prestador una ampliación con precio explícito.';if(seller)actionButtons=button('Marcar servicio realizado','complete',b.id,'');}
 else if(b.status==='COMPLETED_BY_PROVIDER'){actionText=seller?'Marcaste tu parte completada. Falta la confirmación del solicitante.':'El prestador marcó su parte realizada. Confirmá solo si recibiste el servicio o abrí un reclamo.';if(!seller)actionButtons=button('Confirmar servicio recibido '+icon('check'),'confirm',b.id,'');}
 else if(b.status==='COMPLETED'){actionText='Servicio completado. Tu valoración ayuda a que la comunidad tenga información sobre cada experiencia.';if(!d.reviews.some(r=>r.author_id===ctx.user.id)&&b.payment_status==='APPROVED')actionButtons=button('Valorar experiencia '+icon('star'),'review',b.id,'');}
 else if(b.status==='CANCELLED'){actionText='Esta orden está cancelada. Si hubo un pago aprobado, la devolución se solicita a Mercado Pago y se confirma por separado.';}
 else{actionText='Esta operación necesita revisión. Consultá los estados de pago y los reclamos, sin asumir que el dinero está disponible.';}
 if(['CHARGED_BACK','MEDIATION','PAYMENT_REVIEW','REFUND_PENDING','PARTIALLY_REFUNDED'].includes(b.payment_status)){actionText='Hay una incidencia o devolución en el pago. No continúes una prestación hasta aclarar su estado.';actionButtons='';}
 return `${head('Todo sobre tu servicio.','El estado de la prestación y el del pago son independientes.',link('Mis servicios','/ordenes','secondary small'),'ORDEN · '+b.id.slice(0,8).toUpperCase())}<div class="split"><section><div class="panel"><div class="row">${badge(b.status)}${badge(b.payment_status)}${b.kind==='EXTENSION'?'<span class="badge">Ampliación</span>':''}</div><h2 style="margin-top:17px">${h(b.title)}</h2><div class="row muted small">${icon('calendar','tiny-icon')}${dateLabel(b.scheduled_at)} · ${duration(b.blocks)} · Remoto</div><div class="party-row"><a class="party" href="#/perfil/${h(b.buyer_id)}">${avatar(person(ctx,b.buyer_id))}<span><strong>${h(b.buyer_name)}</strong><small>Solicita</small></span></a>${icon('swap')}<a class="party" href="#/perfil/${h(b.seller_id)}">${avatar(person(ctx,b.seller_id))}<span><strong>${h(b.seller_name)}</strong><small>Presta el servicio</small></span></a></div>${b.notes?`<p class="small muted" style="white-space:pre-wrap">${h(b.notes)}</p>`:''}<div class="flow-track">${['Solicitud','Aceptación','En curso','Realizado','Confirmado'].map((t,i)=>`<div class="flow-step ${i<idx?'done':i===idx?'current':''}"><span>${i<idx?icon('check','tiny-icon'):i+1}</span>${t}</div>`).join('')}</div><div class="action-panel"><h3>Tu próximo paso</h3><p>${h(actionText)}</p>${actionButtons}</div><div class="actions">${['REQUESTED','ACCEPTED'].includes(b.status)?button('Cancelar','cancel',b.id,'danger small'):''}${button('Pedir ayuda / reclamar','report-order',b.id,'secondary small')}${seller&&!b.parent_id&&['ACCEPTED','IN_PROGRESS'].includes(b.status)&&b.payment_status==='APPROVED'?button('+ 15 min o más','extension',b.id,'ghost small'):''}${button(icon('download')+' Calendario','export-order',b.id,'ghost small')}</div>${b.cancel_reason?notice(h(b.cancel_reason),'warning'):''}</div><div class="panel chat-panel section"><div class="chat-head"><h3>${icon('chat')}Conversación con ${h(person(ctx,other).name.split(' ')[0])}</h3><p class="small muted">Mensajes privados de esta orden. No compartas claves, documentos ni tarjetas.</p></div><div class="messages" id="messages">${d.messages.length?d.messages.map(m=>`<div class="message ${m.sender_id===ctx.user.id?'mine':''}"><p>${h(m.body)}</p><small>${h(m.sender_name)} · ${dateLabel(m.created_at)}</small></div>`).join(''):'<p class="small muted">Podés empezar por confirmar el alcance y cómo van a conectarse.</p>'}</div><form class="chat-form" data-form="chat" data-id="${h(b.id)}"><div class="suggestions"><button type="button" data-action="draft" data-text="¡Hola! ¿Coordinamos los detalles del servicio?">Coordinar detalles</button><button type="button" data-action="draft" data-text="¿Podemos confirmar qué incluye el servicio?">Confirmar alcance</button><button type="button" data-action="emoji" data-text="👍">👍</button><button type="button" data-action="emoji" data-text="¡Gracias!">¡Gracias!</button></div><div class="chat-compose"><textarea name="body" aria-label="Mensaje" placeholder="Escribí un mensaje…" required maxlength="2000" rows="1"></textarea><button class="btn" type="submit" aria-label="Enviar mensaje">${icon('send')}<span class="send-label">Enviar</span></button></div><div class="chat-counter" id="chat-counter">0 / 2000</div><div class="form-error" role="alert"></div></form></div>${d.children.length?`<section class="panel section"><h3>Ampliaciones con pago separado</h3>${d.children.map(c=>`<a class="list-row" href="#/orden/${h(c.id)}"><div class="grow"><strong>${c.blocks} bloque${c.blocks===1?'':'s'} · ${money(c.gross_cents)}</strong><small>${h(statusLabel(c.payment_status))}</small></div>${icon('chevron')}</a>`).join('')}</section>`:''}${d.reviews.length?`<section class="panel section"><h3>Experiencias compartidas</h3>${notice(d.reviewsRevealed?'Las valoraciones ya se pueden consultar.':'Solo vos podés ver tu valoración. Se revela cuando ambas partes evalúan o transcurren 7 días.')} ${d.reviews.map(r=>`<div class="review-row"><strong>${h(person(ctx,r.author_id).name)}</strong> <span class="review-stars">${'★'.repeat(r.rating)}</span><p>${h(r.comment||'Sin comentario adicional.')}</p></div>`).join('')}</section>`:''}</section><aside><div class="panel"><div class="eyebrow">PRECIO ACORDADO · ARS</div>${quoteBox(b.price_ars,b.blocks)}${notice('Confirmar el servicio no libera dinero. La acreditación y disponibilidad siguen las reglas y plazos de Mercado Pago.')}<div class="small muted">Condiciones aceptadas al contratar:<br><code>${h(b.terms_hash.slice(0,16))}…</code></div></div><div class="panel section"><div class="section-head"><h2>Estado del pago</h2>${button(icon('refresh'),'reconcile',b.id,'secondary small','aria-label="Actualizar pago"')}</div>${d.payments.length?d.payments.map(p=>`<div class="payment-box"><div class="row spread">${badge(p.status.toUpperCase())}<strong>${money(p.amount_cents)}</strong></div><p style="margin-top:12px">Pago #${h(p.id)}<br>Disponibilidad MP: <strong>${h(p.release_status==='pending'?'Pendiente':p.release_status==='released'?'Liberado por MP':p.release_status==='unreported'?'No informada':p.release_status)}</strong>${p.release_date?'<br>Fecha informada: '+dateLabel(p.release_date):''}</p><p>Comisión pactada: ${money(b.commission_cents)}<br>Comisión reportada por MP: ${p.commission_reported_cents===null?'No informada':money(p.commission_reported_cents)}<br>Cargo de procesamiento reportado: ${p.processor_fee_cents===null?'No informado':money(p.processor_fee_cents)}<br>Neto reportado por MP: ${p.net_reported_cents===null?'No informado':money(p.net_reported_cents)}${p.refunded_cents?'<br>Reembolsado: '+money(p.refunded_cents):''}</p></div>`).join(''):'<p class="small muted">Todavía no hay un pago verificado para esta orden. Volver del checkout no acredita por sí solo un pago.</p>'}${d.refunds.map(r=>`<div class="notice warning"><div><strong>Devolución · ${money(r.amount_cents)}</strong><br>${h(statusLabel(r.status))}<br>${h(r.reason)}</div></div>`).join('')}</div>${d.reports.length?`<div class="panel section"><h3>Tus reclamos</h3>${d.reports.map(r=>`<div class="review-row">${badge(r.status)}<p class="small">${h(r.body)}</p>${r.resolution?notice(h(r.resolution)):''}<small class="muted">${h(r.id.slice(0,8))}</small></div>`).join('')}</div>`:''}</aside></div>`;
}
export function checkout(ctx,d){const b=d.booking;if(ctx.user?.id!==b.buyer_id)return accessRequired('Este pago corresponde al solicitante.');return `${head('Un último vistazo antes de pagar.','El precio está acordado. Vos decidís cuándo continuar.',link('Volver a la orden','/orden/'+b.id,'secondary small'),'CHECKOUT')}<div class="split"><section class="panel"><div class="party">${avatar(person(ctx,b.seller_id),'lg')}<div><h2>${h(b.title)}</h2><p class="small muted">Con ${h(b.seller_name)} · ${dateLabel(b.scheduled_at)}</p></div></div>${quoteBox(b.price_ars,b.blocks)}${notice('Mercado Pago procesa el cobro y distribuye el importe. INTERA no guarda tu tarjeta ni mantiene una billetera propia.')}<form data-form="checkout" data-id="${h(b.id)}"><label class="check-label"><input type="checkbox" name="accept" required><span>Revisé <strong>${b.blocks} bloques (${duration(b.blocks)}) por ${money(b.gross_cents)}</strong>. Acepto las <a class="text-link" href="#/condiciones" target="_blank" rel="noopener">condiciones vigentes</a>, la comisión del 5% descontada al prestador y los cargos externos aplicables. No se agrega un 5% extra a este total.</span></label><div class="form-error" role="alert"></div><button type="submit" class="btn full">${icon('shield')}${ctx.config.mode==='mock'?'Abrir simulador de pago':'Continuar a Mercado Pago'}</button></form><div id="simulation-slot"></div></section><aside class="panel soft"><div class="eyebrow">PAGO Y SERVICIO, POR SEPARADO</div><h2>Todo claro desde el principio.</h2><div class="step-tile"><span class="step-num">1</span><div><strong class="small">El prestador acepta</strong><p>La tarifa y la duración quedan guardadas en la orden.</p></div></div><div class="step-tile"><span class="step-num">2</span><div><strong class="small">Mercado Pago confirma</strong><p>Un pago pendiente o rechazado no habilita el servicio.</p></div></div><div class="step-tile"><span class="step-num">3</span><div><strong class="small">La acreditación depende de MP</strong><p>La fecha de liberación no depende del botón de finalización de INTERA.</p></div></div>${ctx.config.mode==='mock'?notice('<strong>Simulación local.</strong> No se abre Mercado Pago ni se mueve dinero real.','warning'):notice('No cierres la orden: podés regresar para consultar el estado aunque se interrumpa la conexión.')}</aside></div>`;}
export function seller(ctx){if(!ctx.user)return accessRequired('Compartí tu talento. Cobrá con claridad.');const account=ctx.data.seller,own=ctx.data.offers.filter(o=>o.provider_id===ctx.user.id),pending=ctx.data.bookings.filter(b=>b.seller_id===ctx.user.id&&b.status==='REQUESTED');return `${head('Tu espacio de prestador.','Elegí la tarifa de cada publicación. INTERA intermedia y descuenta el 5% del bruto.',link(icon('plus')+' Nuevo servicio','/publicar',''),'SOY PRESTADOR')}<div class="split"><section class="panel"><div class="row spread"><span class="stat-icon">${icon('link')}</span>${badge(account?.status||'Sin vincular',account?'':'warning')}</div><h2 style="margin-top:18px">Tu cuenta de Mercado Pago.</h2><p class="muted small">Autorizás a INTERA mediante OAuth para crear checkouts y conciliar tus operaciones. No te pedimos la contraseña de Mercado Pago.</p>${account?`<p class="small">Cuenta vinculada: <strong>${h(account.mp_user_id)}</strong><br>Ambiente: <strong>${h(account.mode)}</strong></p>`:''}<div class="actions">${button(icon('link')+' '+(account?.status==='CONNECTED'?'Renovar vinculación':'Vincular Mercado Pago'),'mp-connect','','')}${account?.status==='CONNECTED'?button('Pausar nuevos cobros','mp-pause','','secondary'):''}</div>${ctx.config.mode==='mock'?notice('La vinculación es ficticia en este simulador. En sandbox/live se abre la autorización oficial de Mercado Pago.','warning'):''}</section><aside class="panel soft"><div class="eyebrow">COMISIÓN TOTAL DE INTERMEDIACIÓN</div><h2>5% del bruto.</h2><p class="small muted">$50 por cada $1.000 del servicio, descontados al prestador. No es una tarifa adicional para el cliente.</p><div class="table-wrap"><table><thead><tr><th>Por bloque</th><th>INTERA</th><th>Antes de MP</th></tr></thead><tbody>${[1000,2500,5000].map(p=>`<tr><td>${money(p*100)}</td><td>${money(p*5)}</td><td>${money(p*95)}</td></tr>`).join('')}</tbody></table></div><p class="small muted" style="margin-top:14px">La columna final no es el neto a recibir. Faltan cargos de procesamiento y retenciones que correspondan.</p></aside></div>${pending.length?`<section class="section"><div class="section-head"><h2>Solicitudes para vos</h2>${link('Todas','/ordenes','ghost small')}</div>${pending.map(b=>orderCard(ctx,b)).join('')}</section>`:''}<section class="section"><div class="section-head"><h2>Mis publicaciones</h2><a href="#/movimientos">Ver pagos y cobros ${icon('arrow','tiny-icon')}</a></div>${own.length?own.map(o=>`<article class="order-card"><div class="row spread"><div><div class="row"><span class="badge ${o.active?'good':'neutral'}">${o.active?'Publicada':'Pausada'}</span><span class="small muted">${h(o.category)}</span></div><h3>${h(o.title)}</h3><span class="small muted">${money(o.price_ars*100)} / 15 min · ${duration(o.blocks)} habitual</span></div><div class="actions">${link('Editar','/publicar?edit='+o.id,'secondary small')}${button(o.active?'Pausar':'Reactivar','toggle-offer',o.id,'ghost small',`data-active="${o.active?'0':'1'}"`)}</div></div></article>`).join(''):empty('Tu primera habilidad puede ayudar a alguien','Publicá con alcance claro y elegí una tarifa.',link('Publicar un servicio','/publicar',''),'briefcase')}</section>`;}
export function needs(ctx){return `${head('¿Qué necesita la comunidad?','Las necesidades orientan la búsqueda. No generan cobros ni créditos.',button(icon('plus')+' Publicar necesidad','need','',''),'NECESIDADES')}<div class="offer-grid">${ctx.data.needs.map(n=>`<article class="panel" data-enter><div class="eyebrow">${icon(categoryIcon(n.category))}${h(n.category)}</div><h3>${h(n.title)}</h3><p class="small muted">${h(n.description)}</p><div class="provider-line">${avatar(person(ctx,n.user_id))}${h(n.requester_name)} · ${h(n.neighborhood)}</div><strong>${money(n.max_price_ars*100)} / bloque máximo</strong><p class="small muted">${n.blocks} bloques · ${duration(n.blocks)}</p><div class="actions">${button('Buscar coincidencias','need-match',n.id,'secondary small')}${n.user_id===ctx.user?.id?button('Cerrar necesidad','need-close',n.id,'ghost small'):''}</div></article>`).join('')}</div>${!ctx.data.needs.length?empty('Todavía no hay necesidades publicadas','Contá qué querés resolver. No se cobra al publicar.',button('Publicar necesidad','need','',''),'list'):''}`;}
export function profile(ctx,p,own=false){if(!p)return accessRequired('Tu espacio, tus conexiones.');const offers=ctx.data.offers.filter(o=>o.provider_id===p.id&&o.active);return `${head(own?'Mi espacio.':'Conocé a '+p.name.split(' ')[0]+'.','La identidad de cada prestación empieza con información clara.',own?button(icon('logout')+' Cerrar sesión','logout','','secondary small'):'','PERFIL')}<section class="panel" style="padding:0"><div class="profile-cover"></div><div class="profile-info">${avatar(p,'xl')}<h1>${h(p.name)}</h1><p>${icon('pin','tiny-icon')}${h(p.neighborhood)}${p.is_demo?' · Perfil ilustrativo de demostración':''}</p><p>${h(p.bio||'Esta persona todavía no agregó una presentación.')}</p>${!own?`<div class="actions">${button('Reportar perfil','report-profile',p.id,'secondary small')}${button('Bloquear / desbloquear','block',p.id,'ghost small')}</div>`:''}</div></section>${own?`<section class="section split"><div class="panel"><h2>Lo que compartís.</h2><form data-form="profile"><label class="field">Nombre<input name="name" value="${h(p.name)}" required minlength="2" maxlength="80"></label><label class="field">Barrio<select name="neighborhood">${ctx.data.neighborhoods.map(n=>`<option ${n===p.neighborhood?'selected':''}>${h(n)}</option>`).join('')}</select></label><label class="field">Presentación<textarea name="bio" maxlength="1000">${h(p.bio)}</textarea></label><div class="form-error" role="alert"></div><button class="btn" type="submit">Guardar mi perfil</button></form></div><aside class="panel"><h2>Tu información, a mano.</h2>${[['/prestador','briefcase','Mi espacio de prestador'],['/movimientos','wallet','Pagos y cobros'],['/agenda','calendar','Mi agenda'],['/necesidades','list','Necesidades de la comunidad'],['/ayuda','help','Ayuda y privacidad']].map(([path,i,t])=>`<a class="list-row" href="#${path}">${icon(i)}<div class="grow"><strong>${t}</strong></div>${icon('chevron')}</a>`).join('')}<div class="actions section">${button(icon('download')+' Exportar mis datos','export-data','','secondary small')}${button('Experiencia visual','settings','','ghost small')}</div><p class="small muted" style="margin-top:17px">Los datos de v1–v4 no se importan como dinero. La exportación es personal y no es una factura.</p></aside></section>`:''}<section class="section"><div class="section-head"><h2>${own?'Mis servicios publicados':'Lo que '+h(p.name.split(' ')[0])+' ofrece'}</h2></div>${offers.length?`<div class="offer-grid">${offers.map(o=>offerCard(ctx,o)).join('')}</div>`:empty('Sin publicaciones activas','Las nuevas habilidades aparecerán acá.',own?link('Publicar servicio','/publicar',''):'','briefcase')}</section>`;}
export function finances(ctx,f){if(!ctx.user)return accessRequired();const selling=f.payments.filter(p=>p.seller_id===ctx.user.id),buying=f.payments.filter(p=>p.buyer_id===ctx.user.id);const sum=rows=>rows.filter(p=>['approved','refunded'].includes(p.status)).reduce((n,p)=>n+p.amount_cents-p.refunded_cents,0);return `${head('Tus pagos. Tus cobros.','Operaciones verificadas con el proveedor de pagos. Esto no es una billetera.',button(icon('download')+' Exportar CSV','export-finances','','secondary small'),'MOVIMIENTOS EN ARS')}<div class="balance-row"><div class="mini-stat"><span class="stat-icon">${icon('briefcase')}</span><div><strong>${money(sum(selling))}</strong><small>Bruto cobrado menos devoluciones · antes de cargos</small></div></div><div class="mini-stat"><span class="stat-icon">${icon('wallet')}</span><div><strong>${money(sum(buying))}</strong><small>Pagado menos devoluciones</small></div></div><div class="mini-stat"><span class="stat-icon">${icon('shield')}</span><div><strong>5%</strong><small>Comisión pactada sobre el bruto</small></div></div></div><section class="section">${notice('La aprobación de un pago no garantiza disponibilidad inmediata. El neto y la liberación informados por Mercado Pago se consultan en cada orden. Los contracargos no se incluyen en los totales confirmados.')} ${f.payments.length?`<div class="table-wrap"><table><thead><tr><th>Servicio / rol</th><th>Bruto</th><th>Comisión pactada</th><th>Reembolsado</th><th>Estado</th><th>Detalle</th></tr></thead><tbody>${f.payments.map(p=>`<tr><td>${h(p.title)}<br><small class="muted">${p.seller_id===ctx.user.id?'Como prestador':'Como solicitante'} · #${h(p.id)}</small></td><td>${money(p.amount_cents)}</td><td>${money(p.agreed_commission_cents)}</td><td>${money(p.refunded_cents)}</td><td>${badge(p.status.toUpperCase())}</td><td><a class="text-link" href="#/orden/${h(p.booking_id)}">Ver orden</a></td></tr>`).join('')}</tbody></table></div>`:empty('Todavía no hay pagos verificados','Un checkout creado o una solicitud aceptada no cuentan como un pago aprobado.',link('Mis servicios','/ordenes',''),'wallet')}</section>${f.entries.length?`<section class="section panel"><h3>Registro de conciliación</h3><p class="small muted">${f.entries.length/3} eventos económicos registrados con asientos compensatorios. Es un registro operativo, no contabilidad fiscal ni fondos custodiados por INTERA.</p>${button('Exportar todos mis registros','export-data','','secondary small')}</section>`:''}`;}
export function agenda(ctx){if(!ctx.user)return accessRequired();const selected=ctx.calendarDate;const base=new Date(ctx.calendarYear,ctx.calendarMonth,1),days=new Date(ctx.calendarYear,ctx.calendarMonth+1,0).getDate(),start=(base.getDay()+6)%7;const all=ctx.data.bookings.filter(b=>!['REQUESTED','CANCELLED'].includes(b.status));const monthEvents=all.filter(b=>new Date(b.scheduled_at).getFullYear()===ctx.calendarYear&&new Date(b.scheduled_at).getMonth()===ctx.calendarMonth);const events=monthEvents.filter(b=>!selected||new Date(b.scheduled_at).getDate()===selected);const now=new Date();return `${head('Hacé lugar a lo que importa.','Tus acuerdos, organizados. Los horarios se muestran en la zona de este dispositivo.',button(icon('download')+' Exportar agenda','export-agenda','','secondary small'),'AGENDA')}<div class="split"><section class="panel"><div class="calendar-controls">${button(icon('chevron'),'month-prev','','secondary small','aria-label="Mes anterior"')}<h3>${h(base.toLocaleString('es-AR',{month:'long',year:'numeric'}))}</h3>${button(icon('chevron'),'month-next','','secondary small','aria-label="Mes siguiente"')}</div><div class="calendar-grid">${['Lun','Mar','Mié','Jue','Vie','Sáb','Dom'].map(d=>`<div class="calendar-head">${d}</div>`).join('')}${Array.from({length:start},()=>'<div class="calendar-day filler"></div>').join('')}${Array.from({length:days},(_,i)=>{const d=i+1,n=monthEvents.filter(e=>new Date(e.scheduled_at).getDate()===d).length,today=now.getDate()===d&&now.getMonth()===ctx.calendarMonth&&now.getFullYear()===ctx.calendarYear;return `<button class="calendar-day ${selected===d?'active':''} ${today?'today':''}" data-action="calendar-day" data-id="${d}" aria-label="Día ${d}, ${n} servicios">${d}${n?'<span class="day-dot"></span><small>'+n+' servicio'+(n===1?'':'s')+'</small>':''}</button>`;}).join('')}</div><div style="margin-top:17px">${button('Ver todo el mes','calendar-day','','ghost small')}</div></section><aside><div class="section-head"><h2>${selected?'Día '+selected:'En este mes'}</h2><span class="small muted">${events.length} acuerdos</span></div>${events.length?events.map(b=>orderCard(ctx,b)).join(''):empty('Un poco de espacio libre','Los acuerdos aceptados aparecerán en la agenda. Revisá el estado de pago antes de comenzar.','','calendar')}</aside></div>`;}
export function terms(ctx){return `${head('Reglas claras para conectar.','Precios, intermediación, pagos, reclamos y privacidad.',ctx.user?button('Aceptar condiciones','terms','',''):'','CONDICIONES DEL SERVICIO')}<section class="panel">${notice('Versión '+h(ctx.legal.version)+' · Huella del documento: <code>'+h(ctx.legal.hash.slice(0,20))+'…</code>')}<pre class="legal">${h(ctx.legal.content)}</pre></section>`;}
export function help(ctx){return `${head('Estamos para ordenar el próximo paso.','Consultá tus operaciones, registrá un reclamo o solicitá acceso y supresión de datos.','','AYUDA Y PRIVACIDAD')}<div class="split"><section class="panel"><h2>Primero, lo importante.</h2>${notice(ctx.config.mode==='mock'?'Este es un entorno local. Los reclamos se guardan en la base de prueba: no hay una persona de soporte conectada.':'El reclamo queda registrado para el operador. No es un servicio de emergencia ni de atención inmediata.','warning')}<form data-form="report"><label class="field">Tipo de solicitud<select name="type"><option value="SUPPORT">Consulta o problema de uso</option><option value="PRIVACY_ACCESS">Acceso o rectificación de mis datos</option><option value="PRIVACY_DELETE">Solicitar eliminación de mi cuenta</option><option value="REFUND_REQUEST">Reclamo o solicitud de devolución</option><option value="WITHDRAWAL">Solicitud de arrepentimiento</option><option value="ABUSE">Abuso o conducta inapropiada</option></select></label><label class="field">Contanos qué necesitás<textarea name="body" minlength="10" maxlength="3000" required placeholder="Incluí la referencia de la orden, sin datos de tarjetas ni contraseñas."></textarea></label><div class="form-error" role="alert"></div><button class="btn" type="submit">Registrar solicitud</button></form>${ctx.config.supportEmail?`<p class="small muted" style="margin-top:16px">Canal del operador: ${h(ctx.config.supportEmail)}</p>`:''}</section><aside class="panel"><h2>Preguntas frecuentes.</h2>${[['¿Qué estoy contratando?','Un servicio con duración acordada en bloques de 15 minutos. La tarifa por bloque es $1.000, $2.500 o $5.000 ARS, elegida por el prestador.'],['¿El 5% se suma al precio?','No. La comisión de INTERA se descuenta del bruto del prestador. Los cargos de Mercado Pago y las retenciones son conceptos distintos.'],['¿Cuándo recibe su dinero el prestador?','Según el estado y plazo que informe Mercado Pago. La confirmación del servicio no libera dinero ni crea una transferencia.'],['¿Qué pasa si cancelo?','Antes de iniciar, se solicita el reembolso de los pagos aprobados. La devolución se marca confirmada al verificarse con Mercado Pago. Después del inicio, corresponde revisión. No se excluyen derechos imperativos.'],['¿Puedo importar mis créditos anteriores?','No. Los datos de versiones anteriores eran simulados; no se convierten en pesos ni en reputación real.']].map(([q,a])=>`<details class="review-row"><summary><strong class="small">${q}</strong></summary><p class="small muted" style="margin-top:10px">${a}</p></details>`).join('')}${link('Leer las condiciones completas','/condiciones','secondary small')}</aside></div>`;}
export function authPage(ctx,kind='login'){const register=kind==='register',forgot=kind==='forgot',reset=kind==='reset',verify=kind==='verify';return `<div class="auth-wrap"><div class="brand"><img src="/assets/intera-mark.svg" alt="">intera</div><section class="panel"><div class="eyebrow">TU PRÓXIMA BUENA CONEXIÓN</div><h1>${register?'Todos tenemos algo para aportar.':forgot||reset?'Recuperá tu acceso.':verify?'Confirmá tu correo.':'Bueno tenerte acá.'}</h1><p class="small muted">${register?'Una cuenta para ofrecer, contratar y organizar tus servicios.':verify?'El enlace es de un solo uso y vence a los 30 minutos.':forgot||reset?'No compartas este enlace ni tu nueva contraseña.':'Ingresá a tu espacio personal.'}</p><form data-form="${kind}">${register?`<label class="field">Nombre y apellido<input name="name" required minlength="2" maxlength="80" autocomplete="name"></label>`:''}${!reset&&!verify?'<label class="field">Correo electrónico<input name="email" type="email" autocomplete="email" required maxlength="254"></label>':''}${!forgot&&!verify?`<label class="field">${reset?'Nueva contraseña':'Contraseña'}<input name="password" type="password" minlength="12" maxlength="128" required autocomplete="${register||reset?'new-password':'current-password'}"><small>${register||reset?'Al menos 12 caracteres. Usá una contraseña única.':''}</small></label>`:''}${register?`<div class="form-grid"><label class="field">Fecha de nacimiento<input name="dob" type="date" required><small>Exclusivamente 18+</small></label><label class="field">Barrio<select name="neighborhood">${ctx.data.neighborhoods.map(n=>`<option>${h(n)}</option>`).join('')}</select></label></div><label class="check-label"><input type="checkbox" name="conditions" required><span>Leí y acepto las <a class="text-link" href="#/condiciones" target="_blank" rel="noopener">condiciones del servicio y privacidad</a>, incluyendo el modelo de bloques pagos y la comisión del 5% para prestadores.</span></label>`:''}<div class="form-error" role="alert"></div><button type="submit" class="btn full">${register?'Crear mi cuenta':forgot?'Enviar instrucciones':reset?'Guardar nueva contraseña':verify?'Verificar mi correo':'Ingresar'}${icon('arrow')}</button></form><div id="auth-notice"></div>${!register&&!forgot&&!reset&&!verify?'<p class="auth-help"><a href="#/recuperar">Olvidé mi contraseña</a></p><p class="auth-help">¿Primera vez? <a href="#/registro">Creá tu cuenta</a></p>':'<p class="auth-help"><a href="#/acceso">Volver a ingresar</a></p>'}${ctx.config.mode==='mock'?`<div style="margin-top:22px">${button('Probar con perfiles de ejemplo','demo','','ghost full small')}</div>`:''}</section></div>`;}
export function compareTray(ctx){const ids=ctx.compare.filter(id=>ctx.data.offers.some(o=>o.id===id));if(!ids.length)return '';return `<aside class="compare-tray" aria-label="Comparador"><span class="stat-icon">${icon('compare')}</span><div><strong>${ids.length} servicio${ids.length===1?'':'s'} para comparar</strong><small>Compará precio, duración y alcance. No reserva ni cobra.</small></div><div class="actions">${button('Comparar ('+ids.length+')','compare-open','','')}${button(icon('close'),'compare-clear','','secondary small','aria-label="Vaciar comparación"')}</div></aside>`;}
export function comparison(ctx){const offers=ctx.compare.map(id=>ctx.data.offers.find(o=>o.id===id)).filter(Boolean);return `<p class="muted small">Hasta tres propuestas. Cada prestador tiene su tarifa por bloque de 15 minutos.</p><div class="compare-cols" style="--columns:${offers.length}">${offers.map(o=>`<div class="compare-cell"><div>${avatar(person(ctx,o.provider_id))}<h3 style="margin-top:12px">${h(o.title)}</h3><strong>${money(o.price_ars*100)}</strong><p>Por bloque · ${duration(o.blocks)} habitual<br>Total habitual: ${money(o.blocks*o.price_ars*100)}</p><p>${h(o.description)}</p>${link('Ver servicio','/oferta/'+o.id,'secondary small')}</div></div>`).join('')}</div>`;}
export function modalWrap(title,content){return `<header class="modal-header"><h2 id="modal-title">${h(title)}</h2><button class="icon-btn" data-action="close-modal" aria-label="Cerrar">${icon('close')}</button></header><div class="modal-content">${content}</div>`;}
export function bookForm(ctx,o){const compatible=ctx.data.needs.filter(n=>n.user_id===ctx.user?.id&&n.category===o.category);return `<p class="small muted">Con ${h(o.provider_name)} · ${h(o.title)}. La solicitud no genera un cobro. El prestador debe aceptar antes de que pagues.</p><form data-form="book" data-id="${h(o.id)}"><div class="form-grid"><label class="field">Cantidad de bloques<input name="blocks" type="number" min="1" max="32" step="1" value="${o.blocks}" required></label><label class="field">Fecha y hora local<input name="scheduledAt" type="datetime-local" value="${dateInput(Date.now()+86400000)}" min="${dateInput(Date.now()+5*60000)}" required></label></div>${compatible.length?`<label class="field">Asociar a una necesidad<select name="needId"><option value="">Sin asociar</option>${compatible.map(n=>`<option value="${h(n.id)}">${h(n.title)}</option>`).join('')}</select></label>`:''}<label class="field">Qué necesitás resolver<textarea name="notes" maxlength="1500" placeholder="Contá el alcance. No compartas información sensible."></textarea></label><div id="book-preview">${quoteBox(o.price_ars,o.blocks)}</div><label class="check-label"><input name="quoteAccepted" type="checkbox" required><span>Revisé el alcance, la duración, el precio y las condiciones vigentes. El precio de esta orden no cambia si el prestador modifica luego su publicación.</span></label><div class="form-error" role="alert"></div><button class="btn full" type="submit">Enviar solicitud ${icon('arrow')}</button></form>`;}
